import java.util.*;
import java.io.*;

public class Main {
    static List<long[]> chooseTable;
    static int R, C;

    public static void main(String[] args) throws IOException {
        redirect(args);
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        String pattern = br.readLine();

        int N = 2 * (R + C);
        chooseTable = new ArrayList<>();
        for (int i = 0; i <= N; i++) {
            long[] row = new long[i + 1];
            row[0] = 1;
            row[i] = 1;
            for (int j = 1; j < i; j++) {
                row[j] = chooseTable.get(i - 1)[j - 1] + chooseTable.get(i - 1)[j];
            }
            chooseTable.add(row);
        }

        long[] opt = solve(repeatChar('?', N));
        long[] score = solve(pattern);
        if (opt[0] == score[0]) {
            System.out.println(score[1]);
        } else {
            System.out.println(0);
        }
    }

    static void redirect(String[] args) {
        // No special redirect needed for Java; placeholder for compatibility
    }

    static long[] solve(String pattern) {
        int N = pattern.length();
        long base_value = 0;
        for (int i = 0; i < R + C; i++) {
            base_value += choose(i, R - 1) * choose(N - i - 1, R);
        }
        long min_diff = Long.MAX_VALUE;
        long total_score = 0;
        long target = 2 * base_value - choose(N, 2 * R);

        long req_mask = 0, excl_mask = 0;
        for (int i = 0; i < N; i++) {
            if (pattern.charAt(i) == 'A') {
                req_mask |= bit(i);
            } else if (pattern.charAt(i) == 'B') {
                excl_mask |= bit(i);
            }
        }

        long[][] dp = new long[R + C + 1][R + C + 1];
        for (long[] row : dp) Arrays.fill(row, 0);
        dp[0][0] = 1;
        for (int j = 0; j <= R + C; j++) {
            for (int k = 0; k <= R + C; k++) {
                if (j >= R - 1 && k >= R)
                    break;
                if (j < R + C && pattern.charAt(j + k) != 'B')
                    dp[j + 1][k] += dp[j][k];
                if (k < R + C && pattern.charAt(j + k) != 'A')
                    dp[j][k + 1] += dp[j][k];
            }
        }

        int M = N - C;
        List<long[]>[] asums2 = new ArrayList[R + C + 1];
        for (int i = 0; i <= R + C; i++) {
            asums2[i] = new ArrayList<>();
        }

        for (int al = R - 1; al <= R + C; al++) {
            List<Long> tempSums = new ArrayList<>();
            recurse(M, N, al, R + C - al, req_mask, excl_mask, 0L, tempSums);
            long[] arr = new long[tempSums.size()];
            for (int i = 0; i < tempSums.size(); i++) arr[i] = tempSums.get(i);
            Arrays.sort(arr, Collections.reverseOrder());
            asums2[al] = new ArrayList<>();
            for (long v : arr) asums2[al].add(v);
        }

        for (int a = R - 1; a <= R + C; a++) {
            for (int b = R; b <= R + C; b++) {
                if (a > R - 1 && b > R)
                    continue;
                if (dp[a][b] == 0)
                    continue;
                int L = a + b;
                for (int l = 0; l <= M - L; l++) {
                    int r = R + C - a - l;
                    if (r > N - M || r < 0)
                        continue;
                    List<Long> sums1List = new ArrayList<>();
                    recurse(L, M, a, l, req_mask, excl_mask, 0L, sums1List);
                    long[] sums1 = new long[sums1List.size()];
                    for (int i = 0; i < sums1List.size(); i++) sums1[i] = sums1List.get(i);
                    Arrays.sort(sums1);
                    long[] sums2 = new long[asums2[a + l].size()];
                    for (int i = 0; i < sums2.length; i++) sums2[i] = asums2[a + l].get(i);
                    Arrays.sort(sums2);
                    int p = 0, q = 0, p2 = 0, q2 = 0;
                    while (p < sums1.length && q < sums2.length) {
                        while (p2 < sums1.length && sums1[p2] == sums1[p]) p2++;
                        while (q2 < sums2.length && sums2[q2] == sums2[q]) q2++;
                        long total = 2 * (sums1[p] + sums2[q]);
                        long diff = Math.abs(total - target);
                        if (diff < min_diff) {
                            min_diff = diff;
                            total_score = 0;
                        }
                        if (diff == min_diff) {
                            total_score += (long)(p2 - p) * (q2 - q) * dp[a][b];
                        }
                        if (total > target)
                            q = q2;
                        else
                            p = p2;
                    }
                }
            }
        }
        return new long[]{min_diff, total_score};
    }

    static long choose(int n, int r) {
        if (n < 0 || r < 0 || r > n) return 0;
        return chooseTable.get(n)[r];
    }

    static long bit(int x) {
        return 1L << x;
    }

    static void recurse(int L, int N, int a, int na, long req, long excl, long cur, List<Long> sums) {
        if (na > N - L)
            return;
        if (L == N) {
            sums.add(cur);
            return;
        }
        long mask = bit(L);
        if ((req & mask) == 0)
            recurse(L + 1, N, a, na, req, excl, cur, sums);
        if (na > 0 && (excl & mask) == 0) {
            long nxt = cur + choose(a, R - 1) * choose(L - a, R);
            recurse(L + 1, N, a + 1, na - 1, req, excl, nxt, sums);
        }
    }

    static void recurse(int L, int N, int a, int na, long req, long excl, long cur, List<Long> sums) {
        if (na > N - L)
            return;
        if (L == N) {
            sums.add(cur);
            return;
        }
        long mask = bit(L);
        if ((req & mask) == 0)
            recurse(L + 1, N, a, na, req, excl, cur, sums);
        if (na > 0 && (excl & mask) == 0) {
            long nxt = cur + choose(a, R - 1) * choose(L - a, R);
            recurse(L + 1, N, a + 1, na - 1, req, excl, nxt, sums);
        }
    }

    static String repeatChar(char c, int count) {
        char[] arr = new char[count];
        Arrays.fill(arr, c);
        return new String(arr);
    }
